{
  "name": "opencode-cockpit",
  "version": "0.11.2",
  "description": "OpenCode superpowers, all in one: installs every opencode-cockpit feature (Shell, Statusline, Review, Updater, Subagents, Trail, Trust), each can be switched off",
  "type": "module",
  "license": "MIT",
  "author": "Codestz",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Codestz/opencode-cockpit.git",
    "directory": "packages/opencode"
  },
  "homepage": "https://cockpit.codestz.dev/",
  "bugs": {
    "url": "https://github.com/Codestz/opencode-cockpit/issues"
  },
  "keywords": [
    "agents",
    "background",
    "opencode",
    "opencode-plugin",
    "permissions",
    "pty",
    "shell",
    "statusline",
    "terminal",
    "tui"
  ],
  "exports": {
    "./server": {
      "types": "./types/server.d.ts",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./types/tui.d.ts",
      "default": "./dist/tui.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0",
    "bun": ">=1.3.5"
  },
  "files": [
    "server.js",
    "tui.js",
    "dist",
    "types",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.33",
    "@opencode-cockpit/client": "0.11.2",
    "@opencode-cockpit/review": "0.11.2",
    "@opencode-cockpit/shell": "0.11.2",
    "@opencode-cockpit/status": "0.11.2",
    "@opencode-cockpit/subagents": "0.11.2",
    "@opencode-cockpit/trail": "0.11.2",
    "@opencode-cockpit/trust": "0.11.2",
    "@opencode-cockpit/updater": "0.11.2"
  },
  "devDependencies": {
    "@opencode-cockpit/client": "0.11.2"
  },
  "bin": {
    "opencode-cockpit": "./dist/bin.js"
  }
}
